(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const shell = document.getElementById('gameShell');
  const ui = {
    intro: document.getElementById('introScreen'), over: document.getElementById('gameoverScreen'),
    hud: document.getElementById('hud'), score: document.getElementById('score'), coins: document.getElementById('coins'), best: document.getElementById('best'),
    finalScore: document.getElementById('finalScore'), finalCoins: document.getElementById('finalCoins'), toast: document.getElementById('toast'), hint: document.getElementById('bottomHint')
  };
  let W = 0, H = 0, dpr = 1, state = 'intro', last = 0, time = 0, spawnClock = 0, distance = 0, coinCount = 0, speed = 19, worldScroll = 0;
  let lane = 0, laneVisual = 0, jumpY = 0, jumpV = 0, sliding = 0, obstacles = [], coins = [], particles = [], audioOn = false, audioCtx = null;
  let best = Number(localStorage.getItem('neonRunBest') || 0), cameraShake = 0, toastTimer = 0;
  const lanes = [-2.25, 0, 2.25];
  ui.best.textContent = String(best).padStart(6, '0');

  function resize() {
    dpr = Math.min(2, window.devicePixelRatio || 1);
    W = canvas.clientWidth; H = canvas.clientHeight;
    canvas.width = Math.round(W * dpr); canvas.height = Math.round(H * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  window.addEventListener('resize', resize); resize();
  const horizon = () => H * (W < 700 ? .33 : .31);
  const focal = () => H * 1.04;
  function proj(x, z, y = 0) {
    const scale = focal() / (z + 9);
    return { x: W * .5 + x * scale, y: horizon() + (3.45 - y) * scale, s: scale };
  }
  function poly(points, fill, stroke, width = 1) {
    ctx.beginPath(); points.forEach((p, i) => { const q = proj(p[0], p[1], p[2] || 0); i ? ctx.lineTo(q.x, q.y) : ctx.moveTo(q.x, q.y); });
    ctx.closePath(); if (fill) { ctx.fillStyle = fill; ctx.fill(); } if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = width; ctx.stroke(); }
  }
  function line(a, b, color, width = 1) {
    const p = proj(a[0], a[1], a[2] || 0), q = proj(b[0], b[1], b[2] || 0);
    ctx.beginPath(); ctx.moveTo(p.x, p.y); ctx.lineTo(q.x, q.y); ctx.strokeStyle = color; ctx.lineWidth = width; ctx.stroke();
  }
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const rand = (a, b) => a + Math.random() * (b - a);

  function drawSky() {
    const grad = ctx.createLinearGradient(0, 0, 0, H);
    grad.addColorStop(0, '#748da0'); grad.addColorStop(.38, '#b8c5c4'); grad.addColorStop(.68, '#e5c4a0'); grad.addColorStop(1, '#e5ab78');
    ctx.fillStyle = grad; ctx.fillRect(0, 0, W, H);
    const sun = ctx.createRadialGradient(W * .65, horizon() * .62, 4, W * .65, horizon() * .62, H * .34);
    sun.addColorStop(0, 'rgba(255,235,184,.62)'); sun.addColorStop(1, 'rgba(255,235,184,0)'); ctx.fillStyle = sun; ctx.fillRect(0, 0, W, H * .75);
    // distant hazy skyline
    ctx.fillStyle = 'rgba(64,85,96,.23)';
    const base = horizon() + 10;
    for (let i = 0; i < 17; i++) {
      const bw = W / 16, x = i * bw - (worldScroll * 2 % bw), bh = H * (.045 + (Math.sin(i * 19) * .5 + .5) * .12);
      ctx.fillRect(x, base - bh, bw - 3, bh + 10);
      if (i % 3 === 0) { ctx.fillRect(x + bw * .35, base - bh - 18, bw * .12, 18); }
    }
    // foreground blocks frame the rail corridor
    for (const side of [-1, 1]) {
      for (let i = 0; i < 5; i++) {
        const x = side < 0 ? i * W * .09 - W * .12 : W - i * W * .09 - W * .12;
        const bh = H * (.1 + ((i * 13 + (side + 1) * 7) % 5) * .035);
        ctx.fillStyle = ['#65747a', '#53666d', '#798387'][i % 3]; ctx.fillRect(x, horizon() - bh + 25, W * .14, bh + 30);
        ctx.fillStyle = 'rgba(232,213,167,.38)';
        for (let r = 0; r < 4; r++) for (let c = 0; c < 3; c++) ctx.fillRect(x + 10 + c * 17, horizon() - bh + 36 + r * 18, 5, 7);
      }
    }
    // elevated station canopy / girders
    ctx.fillStyle = 'rgba(31,48,57,.8)'; ctx.fillRect(0, 0, W, H * .075);
    ctx.fillStyle = '#d8f46c'; ctx.fillRect(0, H * .075, W, 2);
    ctx.fillStyle = 'rgba(20,33,43,.35)';
    for (let x = -W; x < W * 2; x += 95) {
      const px = x - (worldScroll * 10 % 95);
      ctx.fillRect(px, H * .075, 5, H * .19); ctx.fillRect(px + 5, H * .095, 27, 3);
    }
  }
  function drawTrack() {
    poly([[-5.1, 100, 0], [5.1, 100, 0], [5.1, -3, 0], [-5.1, -3, 0]], '#343d42');
    // ballast shoulders
    poly([[-8, 100, 0], [-5.1, 100, 0], [-5.1, -3, 0], [-8, -3, 0]], '#927866');
    poly([[5.1, 100, 0], [8, 100, 0], [8, -3, 0], [5.1, -3, 0]], '#927866');
    // track beds and sleepers
    const offset = worldScroll % 3.2;
    for (let z = 2 - offset; z < 94; z += 3.2) {
      const alpha = clamp(1 - z / 115, .12, .7);
      poly([[-5.1, z + .18, .04], [5.1, z + .18, .04], [5.1, z, .04], [-5.1, z, .04]], `rgba(27,34,37,${alpha})`);
    }
    // steel rails with bright glint
    for (const x of [-3.35, -1.15, 1.15, 3.35]) {
      const p1 = proj(x - .08, 100, .1), p2 = proj(x + .08, 100, .1), p3 = proj(x + .08, -3, .1), p4 = proj(x - .08, -3, .1);
      ctx.fillStyle = '#747d7d'; ctx.beginPath(); ctx.moveTo(p1.x,p1.y);ctx.lineTo(p2.x,p2.y);ctx.lineTo(p3.x,p3.y);ctx.lineTo(p4.x,p4.y);ctx.closePath();ctx.fill();
      line([x - .035, 100, .13], [x - .035, -3, .13], 'rgba(231,235,213,.62)', 1.2);
    }
    // perspective lane markers
    for (let z = 2 - (worldScroll % 8); z < 70; z += 8) {
      line([-0.04, z, .05], [-0.04, z + 3.5, .05], 'rgba(226,224,193,.27)', 1.5);
      line([.04, z, .05], [.04, z + 3.5, .05], 'rgba(226,224,193,.27)', 1.5);
    }
    // platform edges and small lamps
    for (const side of [-1, 1]) {
      line([side * 5.2, 100, .1], [side * 5.2, -3, .1], '#d6c49c', 2.5);
      for (let z = 5 - (worldScroll % 16); z < 90; z += 16) {
        const p = proj(side * 5.5, z, 0);
        ctx.fillStyle = '#25373c'; ctx.fillRect(p.x - p.s * .055, p.y - p.s * .25, p.s * .11, p.s * .25);
        ctx.fillStyle = '#f6d28c'; ctx.shadowColor = '#f6d28c'; ctx.shadowBlur = 9; ctx.beginPath(); ctx.arc(p.x, p.y - p.s * .27, Math.max(1.2, p.s * .045), 0, Math.PI * 2); ctx.fill(); ctx.shadowBlur = 0;
      }
    }
  }
  function roundedRect(x,y,w,h,r,fill,stroke) { ctx.beginPath(); ctx.roundRect(x,y,w,h,r); if(fill){ctx.fillStyle=fill;ctx.fill()} if(stroke){ctx.strokeStyle=stroke;ctx.stroke()} }
  function drawSign(z, side) {
    const x = side * 6.4, p = proj(x, z, 0), top = proj(x, z, 4.5);
    ctx.strokeStyle = '#26363b'; ctx.lineWidth = Math.max(1, p.s * .11); ctx.beginPath(); ctx.moveTo(p.x,p.y);ctx.lineTo(top.x,top.y);ctx.stroke();
    const sw = p.s * 1.15, sh = p.s * .5;
    ctx.fillStyle = '#253f45'; roundedRect(top.x - sw/2, top.y - sh - p.s*.15, sw, sh, 3, '#25464a');
    ctx.fillStyle = '#d8f46c'; ctx.font = `900 ${Math.max(4,p.s*.24)}px sans-serif`; ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('CITY 04',top.x,top.y-sh*.65-p.s*.15);
  }
  function drawEnvironment() {
    drawSky(); drawTrack();
    for (let z = 82 - worldScroll % 28; z > 3; z -= 28) { drawSign(z, -1); drawSign(z + 12, 1); }
    // floating dust flecks near track
    for(let i=0;i<16;i++) { const x=((i*79+worldScroll*1.7)%W), y=horizon()+((i*37+time*8)%(H*.43)); ctx.fillStyle=`rgba(255,238,193,${.06+(i%3)*.035})`;ctx.fillRect(x,y,2,2); }
  }

  function drawCrate(o) {
    const x = lanes[o.lane], z = o.z, w = o.type === 'train' ? 1.65 : 1.35, h = o.type === 'train' ? 3.2 : 1.45;
    const a=proj(x-w/2,z,0),b=proj(x+w/2,z,0),c=proj(x+w/2,z,h),d=proj(x-w/2,z,h);
    // right side depth face
    const side=proj(x+w*.16,z+1.2,0), sideTop=proj(x+w*.16,z+1.2,h);
    ctx.fillStyle=o.type==='train'?'#345b67':'#bd6548'; ctx.beginPath();ctx.moveTo(b.x,b.y);ctx.lineTo(side.x,side.y);ctx.lineTo(sideTop.x,sideTop.y);ctx.lineTo(c.x,c.y);ctx.closePath();ctx.fill();
    ctx.fillStyle=o.type==='train'?'#53818a':'#e8885b';ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.lineTo(c.x,c.y);ctx.lineTo(d.x,d.y);ctx.closePath();ctx.fill();
    ctx.strokeStyle='rgba(36,43,43,.55)';ctx.lineWidth=Math.max(1,a.s*.035);ctx.stroke();
    if(o.type==='train') {
      for(let i=0;i<2;i++){const win=proj(x-w*.28+i*w*.54,z-.02,h*.7);ctx.fillStyle='#c9d5bd';ctx.globalAlpha=.72;ctx.fillRect(win.x-a.s*.18,win.y-a.s*.14,a.s*.36,a.s*.28);ctx.globalAlpha=1;}
      poly([[x-w*.5,z,h*.14],[x+w*.5,z,h*.14],[x+w*.5,z,h*.23],[x-w*.5,z,h*.23]],'#d8f46c');
    } else {
      const stripeY=proj(x,z,h*.58);ctx.fillStyle='#edc566';ctx.save();ctx.translate(stripeY.x,stripeY.y);ctx.rotate(-.08);ctx.fillRect(-a.s*w*.48,-a.s*.075,a.s*w*.96,a.s*.15);ctx.restore();
      line([x-w*.35,z,h*.12],[x+w*.35,z,h*.88],'rgba(115,50,37,.55)',Math.max(1,a.s*.035));
    }
    // soft grounding shadow
    ctx.fillStyle='rgba(19,25,26,.22)';ctx.beginPath();ctx.ellipse(a.x,a.y,a.s*w*.65,a.s*.15,0,0,Math.PI*2);ctx.fill();
  }
  function drawBarrier(o) {
    const x=lanes[o.lane],z=o.z; const left=proj(x-1,z,.66),right=proj(x+1,z,.66),foot=proj(x,z,0);
    const post=proj(x-.77,z,.68),post2=proj(x+.77,z,.68);
    ctx.fillStyle='rgba(18,28,30,.25)';ctx.beginPath();ctx.ellipse(foot.x,foot.y,foot.s*1.05,foot.s*.16,0,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#da7650';ctx.beginPath();ctx.moveTo(left.x,left.y);ctx.lineTo(right.x,right.y);ctx.lineTo(right.x,right.y+foot.s*.22);ctx.lineTo(left.x,left.y+foot.s*.22);ctx.closePath();ctx.fill();
    ctx.fillStyle='#f0cb70';for(let i=0;i<5;i++){const px=left.x+(right.x-left.x)*i/4;ctx.fillRect(px-foot.s*.045,left.y,foot.s*.09,foot.s*.23)}
    for(const p of [post,post2]){ctx.fillStyle='#39444a';ctx.fillRect(p.x-foot.s*.06,p.y,foot.s*.12,foot.s*.6)}
  }
  function drawOverhead(o) {
    const x=lanes[o.lane],z=o.z; const a=proj(x-1.08,z,2.1),b=proj(x+1.08,z,2.1),c=proj(x+1.08,z,2.55),d=proj(x-1.08,z,2.55);
    ctx.fillStyle='#536c70';ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.lineTo(c.x,c.y);ctx.lineTo(d.x,d.y);ctx.closePath();ctx.fill();
    ctx.fillStyle='#d8f46c';ctx.fillRect(a.x,a.y,Math.max(2,b.x-a.x),Math.max(2,a.s*.08));
    for(const xx of [x-1,x+1]){const p=proj(xx,z,0),q=proj(xx,z,2.1);ctx.strokeStyle='#49575a';ctx.lineWidth=Math.max(1,p.s*.07);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke();}
  }
  function drawCoin(c) {
    const p=proj(lanes[c.lane],c.z,1.05+Math.sin(time*5+c.phase)*.08);
    const spin=.35+Math.abs(Math.sin(time*7+c.phase))*.65, r=Math.max(2,p.s*.22);
    ctx.save();ctx.translate(p.x,p.y);ctx.scale(spin,1);
    ctx.shadowColor='#ffd15b';ctx.shadowBlur=r*1.4;ctx.fillStyle='#f7c74d';ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.fill();
    ctx.shadowBlur=0;ctx.strokeStyle='#fff0a1';ctx.lineWidth=Math.max(1,r*.14);ctx.stroke();ctx.fillStyle='#fff0a1';ctx.font=`900 ${r*1.25}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('◆',0,0);ctx.restore();
  }
  function drawRunner() {
    const x=laneVisual*2.25, z=-2, bob=state==='running'&&!jumpY&&!sliding?Math.sin(time*15)*.055:0, lift=jumpY;
    const base=proj(x,z,lift), s=base.s;
    // shadow stretches during jump
    ctx.fillStyle=`rgba(15,23,26,${Math.max(.09,.25-lift*.045)})`;ctx.beginPath();ctx.ellipse(base.x,proj(x,z,0).y,s*.48,s*.13,0,0,Math.PI*2);ctx.fill();
    const crouch=sliding>0, bodyH=crouch?.65:1.13, legH=crouch?.13:.49, torsoY=lift+legH+bob;
    // running limbs, alternate pose
    const run=Math.sin(time*15), armSwing=state==='running'?run*.23:0;
    if(!crouch){
      // back leg
      line([x-.17,z,torsoY],[x-.2+run*.13,z, lift+.08], '#263743',Math.max(3,s*.12));
      line([x+.16,z,torsoY],[x+.18-run*.13,z,lift+.08], '#243541',Math.max(3,s*.12));
      // bright sneakers
      poly([[x-.35+run*.13,z-.02,lift+.06],[x-.12+run*.13,z-.02,lift+.06],[x-.1+run*.13,z-.02,lift+.18],[x-.33+run*.13,z-.02,lift+.18]],'#f6f1dc');
      poly([[x+.08-run*.13,z-.02,lift+.06],[x+.32-run*.13,z-.02,lift+.06],[x+.31-run*.13,z-.02,lift+.18],[x+.09-run*.13,z-.02,lift+.18]],'#f6f1dc');
    }
    // backpack
    const pack=proj(x-.27,z+.08,torsoY+.26);ctx.fillStyle='#e65d50';roundedRect(pack.x-s*.13,pack.y-s*.1,s*.27,s*.48,s*.06,'#e65d50');
    // torso, angled jacket silhouette
    const shoulder=torsoY+bodyH*.88, waist=torsoY+.12;
    poly([[x-.31,z,waist],[x+.3,z,waist],[x+.25,z,shoulder],[x-.23,z,shoulder]],'#226b72');
    poly([[x-.31,z-.015,waist],[x+.3,z-.015,waist],[x+.24,z-.015,waist+.13],[x-.27,z-.015,waist+.13]],'#e0bd72');
    // arms
    line([x-.26,z,shoulder-.08],[x-.39-armSwing,z,lift+.58], '#e8b37e',Math.max(3,s*.095));
    line([x+.26,z,shoulder-.08],[x+.38+armSwing,z,lift+.58], '#e8b37e',Math.max(3,s*.095));
    line([x-.26,z-.015,shoulder-.09],[x-.4-armSwing,z-.015,lift+.82], '#d85d4d',Math.max(4,s*.12));
    line([x+.26,z-.015,shoulder-.09],[x+.39+armSwing,z-.015,lift+.82], '#d85d4d',Math.max(4,s*.12));
    // neck and head
    const head=proj(x,z,shoulder+.29);const hr=s*.205;
    ctx.fillStyle='#eabb8a';ctx.beginPath();ctx.ellipse(head.x,head.y,hr,hr*1.13,0,0,Math.PI*2);ctx.fill();
    // cap
    const capY=head.y-hr*.68;ctx.fillStyle='#f2cb62';ctx.beginPath();ctx.ellipse(head.x,capY,hr*1.1,hr*.47,0,Math.PI,Math.PI*2);ctx.fill();ctx.fillRect(head.x-hr,capY,hr*2,hr*.28);
    ctx.fillStyle='#344046';ctx.beginPath();ctx.arc(head.x+hr*.32,head.y,Math.max(1,hr*.07),0,Math.PI*2);ctx.fill();
  }
  function render() {
    ctx.save(); if(cameraShake>0){ctx.translate(rand(-cameraShake,cameraShake),rand(-cameraShake,cameraShake));cameraShake*=.82;if(cameraShake<.2)cameraShake=0;}
    drawEnvironment();
    const things=[...obstacles.map(o=>({kind:'obs',item:o,z:o.z})),...coins.map(c=>({kind:'coin',item:c,z:c.z}))].sort((a,b)=>b.z-a.z);
    for(const t of things) { if(t.kind==='coin')drawCoin(t.item);else if(t.item.type==='barrier')drawBarrier(t.item);else if(t.item.type==='overhead')drawOverhead(t.item);else drawCrate(t.item); }
    drawRunner();
    // little impact sparks
    particles.forEach(p=>{const q=proj(p.x,p.z,p.y);ctx.fillStyle=`rgba(255,220,112,${p.life})`;ctx.beginPath();ctx.arc(q.x,q.y,Math.max(1,q.s*.06),0,Math.PI*2);ctx.fill();});
    ctx.restore();
  }

  function updateHud() {
    const score=Math.floor(distance);
    ui.score.textContent=String(score).padStart(6,'0');ui.coins.textContent=coinCount;
  }
  function startGame() {
    state='running'; distance=0;coinCount=0;speed=19;spawnClock=.65;worldScroll=0;lane=0;laneVisual=0;jumpY=0;jumpV=0;sliding=0;obstacles=[];coins=[];particles=[];cameraShake=0;
    ui.intro.classList.add('hidden');ui.over.classList.add('hidden');ui.hud.classList.add('active');ui.hint.classList.add('active');shell.classList.add('running');updateHud();
  }
  function endGame() {
    if(state!=='running')return;state='over';cameraShake=9;ui.hint.classList.remove('active');
    const score=Math.floor(distance);if(score>best){best=score;localStorage.setItem('neonRunBest',String(best));ui.best.textContent=String(best).padStart(6,'0');}
    ui.finalScore.innerHTML=`${score} <small>m</small>`;ui.finalCoins.textContent=coinCount;ui.over.classList.remove('hidden');
    if(audioOn) tone(115,.3,'sawtooth',.045);
  }
  function move(dir) { if(state!=='running')return;lane=clamp(lane+dir,-1,1);tone(300,.045,'sine',.018); }
  function jump() { if(state!=='running')return;if(jumpY<.04&&!sliding){jumpV=8.2;tone(420,.08,'sine',.025);} }
  function slide() { if(state!=='running')return;if(jumpY<.35)sliding=.72; }
  function action(name) { if(name==='left')move(-1);else if(name==='right')move(1);else if(name==='jump')jump();else if(name==='slide')slide(); }
  function makeWave() {
    const blocked=[];
    const count=Math.random()<.38?2:1;
    const first=Math.floor(Math.random()*3);blocked.push(first);
    if(count===2){let second=Math.floor(Math.random()*3);while(second===first)second=Math.floor(Math.random()*3);blocked.push(second);}
    const types=['crate','train','barrier','overhead'];
    blocked.forEach((l,i)=>{
      const type=types[Math.floor(Math.random()*types.length)];
      obstacles.push({lane:l,z:79+i*.45,type,hit:false});
    });
    const safe=[0,1,2].filter(l=>!blocked.includes(l));
    const coinLane=safe.length?safe[Math.floor(Math.random()*safe.length)]:Math.floor(Math.random()*3);
    for(let i=0;i<5;i++)coins.push({lane:coinLane,z:76-i*3.1,phase:Math.random()*6});
    // occasional tempting coin trail in a neighboring lane
    if(Math.random()<.28){const l=(coinLane+1+Math.floor(Math.random()*2))%3;for(let i=0;i<3;i++)coins.push({lane:l,z:72-i*3.2,phase:Math.random()*6});}
  }
  function collect(c) {
    coinCount++;c.got=true;toastTimer=0.72;ui.toast.textContent=coinCount%5===0?'COIN STREAK!':'NICE PICKUP!';ui.toast.classList.add('show');
    const x=lanes[c.lane];for(let i=0;i<5;i++)particles.push({x:x+rand(-.22,.22),z:-1,y:rand(.8,2),life:1,vy:rand(1,3)});
    if(audioOn)tone(760,.09,'sine',.045);
  }
  function tick(dt) {
    time+=dt;
    if(state==='running') {
      speed=Math.min(34,19+distance*.009);distance+=speed*dt;worldScroll+=speed*dt;
      laneVisual+=(lane-laneVisual)*Math.min(1,dt*12);
      if(jumpY>0||jumpV>0){jumpY+=jumpV*dt;jumpV-=20*dt;if(jumpY<=0){jumpY=0;jumpV=0;}}
      if(sliding>0)sliding=Math.max(0,sliding-dt);
      spawnClock-=dt;if(spawnClock<=0){makeWave();spawnClock=rand(1.18,1.52)*Math.max(.78,19/speed);}
      obstacles.forEach(o=>o.z-=speed*dt);coins.forEach(c=>c.z-=speed*dt);
      obstacles=obstacles.filter(o=>o.z>-5);coins=coins.filter(c=>c.z>-5&&!c.got);
      for(const c of coins){if(!c.got&&c.z<2&&c.z>-2&&Math.abs(laneVisual-c.lane)<.48)collect(c);}
      for(const o of obstacles){
        if(!o.hit&&o.z<1.2&&o.z>-1.2&&Math.abs(laneVisual-o.lane)<.48){
          o.hit=true;
          const passed= o.type==='barrier'&&jumpY>.65 || o.type==='overhead'&&sliding>0;
          if(!passed){endGame();break;}else{cameraShake=1.5;}
        }
      }
      updateHud();
    } else if(state==='intro') worldScroll+=dt*2.8;
    particles=particles.filter(p=>p.life>0);particles.forEach(p=>{p.life-=dt*1.8;p.y+=p.vy*dt;p.z-=dt*2;});
    if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show');}
  }
  function frame(now) {
    const dt=Math.min(.04,(now-last)/1000||0);last=now;tick(dt);render();requestAnimationFrame(frame);
