  function render(){ctx.save();if(cameraShake>0){ctx.translate(rand(-cameraShake,cameraShake),rand(-cameraShake,cameraShake));cameraShake*=.82;if(cameraShake<.2)cameraShake=0}drawEnvironment();const things=[...obstacles.map(item=>({kind:'obs',item,z:item.z})),...coins.map(item=>({kind:'coin',item,z:item.z}))].sort((a,b)=>b.z-a.z);for(const t of things){if(t.kind==='coin')drawCoin(t.item);else if(t.item.type==='barrier')drawBarrier(t.item);else if(t.item.type==='overhead')drawOverhead(t.item);else drawCrate(t.item)}drawRunner();particles.forEach(p=>{const q=proj(p.x,p.z,p.y);ctx.fillStyle=`rgba(255,220,112,${p.life})`;ctx.beginPath();ctx.arc(q.x,q.y,Math.max(1,q.s*.06),0,Math.PI*2);ctx.fill()});ctx.restore()}
  function updateHud(){ui.score.textContent=String(Math.floor(distance)).padStart(6,'0');ui.coins.textContent=coinCount}
  function startGame(){state='running';distance=0;coinCount=0;speed=19;spawnClock=.65;worldScroll=0;lane=0;laneVisual=0;jumpY=0;jumpV=0;sliding=0;obstacles=[];coins=[];particles=[];cameraShake=0;ui.intro.classList.add('hidden');ui.over.classList.add('hidden');ui.hud.classList.add('active');ui.hint.classList.add('active');shell.classList.add('running');updateHud()}
  function endGame(){if(state!=='running')return;state='over';cameraShake=9;ui.hint.classList.remove('active');const score=Math.floor(distance);if(score>best){best=score;localStorage.setItem('neonRunBest',String(best));ui.best.textContent=String(best).padStart(6,'0')}ui.finalScore.innerHTML=`${score} <small>m</small>`;ui.finalCoins.textContent=coinCount;ui.over.classList.remove('hidden');if(audioOn)tone(115,.3,'sawtooth',.045)}
  function move(dir){if(state!=='running')return;lane=clamp(lane+dir,-1,1);tone(300,.045,'sine',.018)}
  function jump(){if(state==='running'&&jumpY<.04&&!sliding){jumpV=8.2;tone(420,.08,'sine',.025)}}function slide(){if(state==='running'&&jumpY<.35)sliding=.72}
  function action(name){if(name==='left')move(-1);else if(name==='right')move(1);else if(name==='jump')jump();else if(name==='slide')slide()}
  function makeWave(){const blocked=[],count=Math.random()<.38?2:1,first=Math.floor(Math.random()*3);blocked.push(first);if(count===2){let second=Math.floor(Math.random()*3);while(second===first)second=Math.floor(Math.random()*3);blocked.push(second)}const types=['crate','train','barrier','overhead'];blocked.forEach((l,i)=>obstacles.push({lane:l,z:79+i*.45,type:types[Math.floor(Math.random()*types.length)],hit:false}));const safe=[0,1,2].filter(l=>!blocked.includes(l)),coinLane=safe.length?safe[Math.floor(Math.random()*safe.length)]:Math.floor(Math.random()*3);for(let i=0;i<5;i++)coins.push({lane:coinLane,z:76-i*3.1,phase:Math.random()*6});if(Math.random()<.28){const l=(coinLane+1+Math.floor(Math.random()*2))%3;for(let i=0;i<3;i++)coins.push({lane:l,z:72-i*3.2,phase:Math.random()*6)}}}
  function collect(c){coinCount++;c.got=true;toastTimer=.72;ui.toast.textContent=coinCount%5===0?'COIN STREAK!':'NICE PICKUP!';ui.toast.classList.add('show');const x=lanes[c.lane];for(let i=0;i<5;i++)particles.push({x:x+rand(-.22,.22),z:-1,y:rand(.8,2),life:1,vy:rand(1,3)});if(audioOn)tone(760,.09,'sine',.045)}
  function tick(dt){time+=dt;if(state==='running'){speed=Math.min(34,19+distance*.009);distance+=speed*dt;worldScroll+=speed*dt;laneVisual+=(lane-laneVisual)*Math.min(1,dt*12);if(jumpY>0||jumpV>0){jumpY+=jumpV*dt;jumpV-=20*dt;if(jumpY<=0){jumpY=0;jumpV=0}}if(sliding>0)sliding=Math.max(0,sliding-dt);spawnClock-=dt;if(spawnClock<=0){makeWave();spawnClock=rand(1.18,1.52)*Math.max(.78,19/speed)}obstacles.forEach(o=>o.z-=speed*dt);coins.forEach(c=>c.z-=speed*dt);obstacles=obstacles.filter(o=>o.z>-5);coins=coins.filter(c=>c.z>-5&&!c.got);for(const c of coins)if(!c.got&&c.z<2&&c.z>-2&&Math.abs(laneVisual-c.lane)<.48)collect(c);for(const o of obstacles)if(!o.hit&&o.z<1.2&&o.z>-1.2&&Math.abs(laneVisual-o.lane)<.48){o.hit=true;const passed=o.type==='barrier'&&jumpY>.65||o.type==='overhead'&&sliding>0;if(!passed){endGame();break}else cameraShake=1.5}updateHud()}else if(state==='intro')worldScroll+=dt*2.8;particles=particles.filter(p=>p.life>0);particles.forEach(p=>{p.life-=dt*1.8;p.y+=p.vy*dt;p.z-=dt*2});if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show')}}
  function frame(now){const dt=Math.min(.04,(now-last)/1000||0);last=now;tick(dt);render();requestAnimationFrame(frame)}
  function tone(freq,duration,wave='sine',volume=.03){if(!audioOn)return;try{audioCtx||=new(window.AudioContext||window.webkitAudioContext)();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=wave;osc.frequency.value=freq;gain.gain.setValueAtTime(volume,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);osc.connect(gain);gain.connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+duration)}catch(e){}}
  document.getElementById('playButton').addEventListener('click',startGame);document.getElementById('againButton').addEventListener('click',startGame);
  document.getElementById('soundButton').addEventListener('click',()=>{audioOn=!audioOn;document.getElementById('soundIcon').textContent=audioOn?'♫':'♪';if(audioOn)tone(520,.1)});
  document.querySelectorAll('.touch-controls button').forEach(button=>button.addEventListener('pointerdown',e=>{e.preventDefault();action(button.dataset.action)}));
  window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup','arrowdown',' ','a','d','w','s'].includes(k))e.preventDefault();if(state==='intro'&&(k===' '||k==='enter')||state==='over'&&(k===' '||k==='enter')){startGame();return}if(k==='arrowleft'||k==='a')action('left');if(k==='arrowright'||k==='d')action('right');if(k==='arrowup'||k==='w'||k===' ')action('jump');if(k==='arrowdown'||k==='s')action('slide')},{passive:false});
  let touchStart=null;canvas.addEventListener('touchstart',e=>{const t=e.changedTouches[0];touchStart={x:t.clientX,y:t.clientY}},{passive:true});canvas.addEventListener('touchend',e=>{if(!touchStart)return;const t=e.changedTouches[0],dx=t.clientX-touchStart.x,dy=t.clientY-touchStart.y;touchStart=null;if(Math.max(Math.abs(dx),Math.abs(dy))<24)return;if(Math.abs(dx)>Math.abs(dy))action(dx<0?'left':'right');else action(dy<0?'jump':'slide')},{passive:true});
  requestAnimationFrame(frame);
})();

